def official_role(Role, body):
    """The body's Official role: the template, or a new one if the body already named a role Official."""
    found = Role.objects.filter(organization=body, key="official").first()
    if found:
        return found
    name = "Official"
    if Role.objects.filter(organization=body, name__iexact=name).exists():
        name = "Official (approves tournaments)"
    return Role.objects.create(
        organization=body, key="official", name=name, permissions=["tournaments.approve"]
    )


def appointments_to_bodies(apps, schema_editor):
    """Decision D4: authority moves from individual appointments to body membership. Every existing body
    gets the Official role; each appointment becomes an active membership of its region's body, or of its
    country's national body when it names no region, creating the body if it is missing. The body's first
    appointee becomes the admin of a body created here; everyone else holds Official. Appointments stay
    as read-only history."""
    Organization = apps.get_model("organizations", "Organization")
    Role = apps.get_model("organizations", "Role")
    Membership = apps.get_model("organizations", "Membership")
    OfficialAppointment = apps.get_model("organizations", "OfficialAppointment")
    for body in Organization.objects.filter(kind__in=BODIES):
        official_role(Role, body)
    appointments = OfficialAppointment.objects.select_related("user", "country", "region")
    for appointment in appointments.order_by("id"):
        country = appointment.country
        region = appointment.region
        if region is not None and region.country_id != country.pk:
            continue  # an inconsistent appointment names no jurisdiction; it stays as history
        if region is not None:
            body = Organization.objects.filter(
                kind="regional_body", country=country.pk, region__iexact=region.name
            ).first()
            place, kind, region_name = region.name, "regional_body", region.name
        else:
            body = Organization.objects.filter(kind="national_body", country=country.pk).first()
            place, kind, region_name = country.name, "national_body", ""
        if body is None:
            body = Organization.objects.create(
                name=f"{place} {'regional' if region else 'national'} body"[:120],
                town=place[:80],
                country=country.pk,
                region=region_name,
                kind=kind,
            )
            for key, name, permissions in TEMPLATES:
                Role.objects.create(organization=body, key=key, name=name, permissions=sorted(permissions))
        membership, _ = Membership.objects.get_or_create(organization=body, user=appointment.user)
        if membership.status != "active":
            membership.status = "active"
            membership.save(update_fields=["status"])
        has_admin = Membership.objects.filter(
            organization=body, status="active", roles__key="admin", user__is_active=True
        ).exists()
        if has_admin:
            if not membership.roles.filter(key="admin").exists():
                membership.roles.add(official_role(Role, body))
        else:
            membership.roles.add(Role.objects.get(organization=body, key="admin"))


